 	)

 	report := runStatsJSON(t, "--repo", repo,
 		"--transcript", filepath.Join(sessions, "s1.jsonl"), "--format", "json", "--since", "all")

 	if report.Sessions != 1 {
 		t.Fatalf("sessions = %d, want 1 (subagent must fold into its owner)", report.Sessions)
