package cli

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"strings"

	"github.com/entireio/entire-graph/internal/sem"
)

type snapshotQueryFlags struct {
	Input    string
	Symbol   string
	From     string
	Relation string
	Format   string
}

func runSnapshotQuery(opts Options, args []string) error {
	flags, err := parseSnapshotQueryFlags(args)
	if err != nil {
		return err
	}
	file, err := os.Open(flags.Input)
	if err != nil {
		return fmt.Errorf("open compact snapshot: %w", err)
	}
	defer file.Close()
	index, err := sem.LoadCompactSnapshot(file)
	if err != nil {
		return fmt.Errorf("load compact snapshot: %w", err)
	}
	result := index.Query(sem.CompactSnapshotQuery{Symbol: flags.Symbol, FromID: flags.From, Relation: flags.Relation})
	encoder := json.NewEncoder(opts.Stdout)
	encoder.SetEscapeHTML(false)
	for _, symbol := range result.Symbols {
		if err := encoder.Encode(symbol); err != nil {
			return err
		}
	}
	for _, relation := range result.Relations {
		if err := encoder.Encode(relation); err != nil {
			return err
		}
	}
	return nil
}

func parseSnapshotQueryFlags(args []string) (snapshotQueryFlags, error) {
	flags := snapshotQueryFlags{Format: "ndjson"}
	for i := 0; i < len(args); i++ {
		switch args[i] {
		case "--input":
			i++
			if i >= len(args) {
				return flags, errors.New("--input requires a value")
			}
			flags.Input = args[i]
		case "--symbol":
			i++
			if i >= len(args) {
				return flags, errors.New("--symbol requires a value")
			}
			flags.Symbol = args[i]
		case "--from":
			i++
			if i >= len(args) {
				return flags, errors.New("--from requires a value")
			}
			flags.From = args[i]
		case "--relation":
			i++
			if i >= len(args) {
				return flags, errors.New("--relation requires a value")
			}
			flags.Relation = strings.ToUpper(args[i])
		case "--format":
			i++
			if i >= len(args) {
				return flags, errors.New("--format requires a value")
			}
			flags.Format = args[i]
		default:
			return flags, fmt.Errorf("snapshot-query received unexpected argument %q", args[i])
		}
	}
	if flags.Input == "" {
		return flags, errors.New("snapshot-query requires --input")
	}
	if flags.Symbol == "" && flags.From == "" {
		return flags, errors.New("snapshot-query requires at least --symbol or --from")
	}
	if flags.Relation != "" && flags.From == "" {
		return flags, errors.New("--relation requires --from")
	}
	if flags.Format != "ndjson" {
		return flags, errors.New("snapshot-query requires --format ndjson")
	}
	return flags, nil
}
	DisambiguationRequired bool                   `json:"disambiguation_required"`
	Matches                []neighborFocus        `json:"matches"`
	Warnings               []sem.ProviderWarning  `json:"warnings,omitempty"`
	PartialFailures        []sem.PartialFailure   `json:"partial_failures"`
	Stats                  sem.ProviderStats      `json:"stats"`
	Completeness           sem.CompletenessReport `json:"completeness"`
	// CompletenessScope is the query-relative reading of the diagnostics above.
	// The full lists stay untouched; this says which of them can matter here.
	CompletenessScope completenessScope `json:"completeness_scope"`

	// endpointTruncated distinguishes a bounded neighbor list from the JSON-only
	// explicit path expansion. Agent output can express the full Cartesian path
	// family compactly, so path expansion alone is not a truncation for agents.
	endpointTruncated bool
}

func runNeighbors(ctx context.Context, opts Options, args []string) error {
	flags, err := parseNeighborFlags(args)
	if err != nil {
		return err
	}
	repo, err := resolveRepo(ctx, opts.Env, flags.Repo)
	if err != nil {
		return err
	}
	profile, err := parseProfile(flags.Profile)
	if err != nil {
		return err
	}
	cacheDir := resolveCacheDir(flags.CacheDir, opts.Env.PluginDataDir)
	totalStarted := time.Now()
	indexStarted := totalStarted
	snapshot, cacheHit, err := sem.LoadOrBuildProviderSnapshot(ctx, repo, opts.Version, sem.ProviderSnapshotOptions{
		NoNetwork:    true,
		Worktree:     flags.Worktree,
		IgnoreFiles:  flags.IgnoreFile,
		IncludeFiles: flags.IncludeFile,
		Profile:      profile,
	}, cacheDir, flags.DisableCache)
	if err != nil {
		return err
	}
	indexLatency := time.Since(indexStarted)
	queryStarted := time.Now()
	response := buildNeighborResponse(snapshot, flags)
	// Call-site resolution reads the caller's source, so it needs the repo on
	// disk. It runs after the graph query and is bounded by the answer's size.
	annotateNeighborCallSites(&response, newRepoLineReader(snapshot.Header.RepoRoot))
	queryLatency := time.Since(queryStarted)
	response.IndexCacheHit = cacheHit
	response.IndexCacheDisabled = cacheDir == "" || flags.DisableCache
	response.IndexLatencyMS = indexLatency.Milliseconds()
	response.QueryLatencyMS = queryLatency.Milliseconds()
	response.TotalLatencyMS = time.Since(totalStarted).Milliseconds()
	switch flags.Format {
	case "json":
		encoder := json.NewEncoder(opts.Stdout)
		encoder.SetEscapeHTML(false)
		return encoder.Encode(response)
	case "agent":
		return writeAgentNeighborsBounded(opts.Stdout, response, flags.MaxContextBytes)
	case "text":
		return writeAgentNeighbors(opts.Stdout, response)
	default:
		return fmt.Errorf("neighbors --format must be json, text, or agent, got %q", flags.Format)
	}
}

func parseNeighborFlags(args []string) (neighborFlags, error) {
	flags := neighborFlags{
		Format: "json", Profile: "full", Relation: "CALLS", Direction: "both",
			}
